-- Rebuild Medina Book 3 lesson 14 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 55-59.
-- Eight Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF pages 56-57.
-- The verse وَإِنْ جَنَحُوا لِلسَّلْمِ... is preserved in source position but publicly classified with the imperative-answer case it exemplifies.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '14';
  if old_rule_count <> 3 then raise exception 'Expected 3 generated Book 3 lesson 14 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '14');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '14');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '14';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '14', 'إِذَا الشَّرْطِيَّةُ (условное обстоятельственное имя إِذَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">إِذَا</span> ظَرْفٌ لِمَا يُسْتَقْبَلُ مِنَ الزَّمَانِ، مَبْنِيٌّ عَلَى السُّكُونِ، مُتَضَمِّنٌ مَعْنَى الشَّرْطِ، وَهُوَ غَيْرُ جَازِمٍ.</span><p class="rule-study-text">Это неизменяемое обстоятельственное имя будущего времени со смыслом условия; оно не ставит глагол в джазм.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Свойства إِذَا</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَاصِّيَّةُ</span><span class="rule-table-ru">свойство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَرْحُهَا</span><span class="rule-table-ru">объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفٌ لِلزَّمَانِ الْمُسْتَقْبَلِ</span><span class="rule-table-ru">обстоятельственное имя будущего времени</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدُلُّ عَلَى زَمَانٍ مُسْتَقْبَلٍ</span><span class="rule-table-ru">указывает на будущее время</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى السُّكُونِ</span><span class="rule-table-ru">построено на сукуне</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ</span><span class="rule-table-ru">находится в синтаксическом месте винительного падежа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مُتَضَمِّنٌ مَعْنَى الشَّرْطِ</span><span class="rule-table-ru">содержит смысл условия</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">غَيْرُ جَازِمٍ</span><span class="rule-table-ru">не управляет джазмом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَدْخُلُ غَالِبًا عَلَى الْفِعْلِ الْمَاضِي</span><span class="rule-table-ru">чаще входит перед прошедшим глаголом</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُحَوِّلُ مَعْنَاهُ إِلَى الْمُسْتَقْبَلِ</span><span class="rule-table-ru">переносит его значение в будущее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَدْ تَدْخُلُ عَلَى الْمُضَارِعِ</span><span class="rule-table-ru">может входить перед настоящим-будущим глаголом</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِي الشَّرْطِ وَفِي الْجَوَابِ</span><span class="rule-table-ru">как в условии, так и в ответе</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все прозаические примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الزَّمَانُ فِي اللَّفْظِ وَالْمَعْنَى</span><span class="rule-table-ru">форма и временной смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا جَاءَ رَمَضَانُ فُتِحَتْ أَبْوَابُ الْجَنَّةِ.</span><span class="rule-table-ru">Когда наступает Рамадан, открываются врата Рая.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَاءَ، فُتِحَتْ</span><span class="rule-table-ru">прошедшая форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى مُسْتَقْبَلٌ</span><span class="rule-table-ru">значение относится к будущему</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا رَنَّ الْجَرَسُ خَرَجَ الطُّلَّابُ مِنَ الْفَصْلِ.</span><span class="rule-table-ru">Когда звонит звонок, студенты выходят из класса.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَنَّ، خَرَجَ</span><span class="rule-table-ru">прошедшая форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى مُسْتَقْبَلٌ</span><span class="rule-table-ru">значение относится к будущему</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا حَضَرَ الْمَاءُ بَطَلَ التَّيَمُّمُ.</span><span class="rule-table-ru">Когда появляется вода, таяммум становится недействительным.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَضَرَ، بَطَلَ</span><span class="rule-table-ru">прошедшая форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى مُسْتَقْبَلٌ</span><span class="rule-table-ru">значение относится к будущему</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Стихотворный пример и разметка автора</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّطْرُ</span><span class="rule-table-ru">строка и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ</span><span class="rule-table-ru">глагол условия</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَالنَّفْسُ رَاغِبَةٌ إِذَا رَغَّبْتَهَا</span><span class="rule-table-ru">Душа желает, когда ты возбуждаешь в ней желание.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَغَّبْتَهَا: فِعْلٌ مَاضٍ</span><span class="rule-table-ru">прошедший глагол</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَحْذُوفٌ</span><span class="rule-table-ru">ответ опущен</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَإِذَا تُرَدُّ إِلَى قَلِيلٍ تَقْنَعُ</span><span class="rule-table-ru">А когда её возвращают к малому, она довольствуется.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُرَدُّ: مُضَارِعٌ مَرْفُوعٌ</span><span class="rule-table-ru">настояще-будущий глагол в именительном состоянии</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَقْنَعُ: مُضَارِعٌ مَرْفُوعٌ</span><span class="rule-table-ru">ответ — настояще-будущий глагол в именительном состоянии</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Условное إِذَا — неизменяемое обстоятельственное имя будущего времени: оно содержит смысл условия, но не управляет джазмом.', 'إِذَا ظَرْفٌ لِمَا يُسْتَقْبَلُ مِنَ الزَّمَانِ، مَبْنِيٌّ عَلَى السُّكُونِ، مُتَضَمِّنٌ مَعْنَى الشَّرْطِ، وَهُوَ غَيْرُ جَازِمٍ. تَدْخُلُ غَالِبًا عَلَى الْفِعْلِ الْمَاضِي فَتُحَوِّلُ مَعْنَاهُ إِلَى الْمُسْتَقْبَلِ، وَقَدْ تَدْخُلُ عَلَى الْمُضَارِعِ فِي الشَّرْطِ وَالْجَوَابِ.'),
    ('Мединский курс (Том 3)', '14', 'وُجُوبُ اقْتِرَانِ جَوَابِ الشَّرْطِ بِالْفَاءِ (обязательная фа в ответе условия)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَجِبُ اقْتِرَانُ جَوَابِ الشَّرْطِ <span class="ar-tone-particle">بِالْفَاءِ</span> فِي ثَمَانِيَةِ مَوَاضِعَ، سَوَاءٌ أَكَانَتْ أَدَاةُ الشَّرْطِ جَازِمَةً أَمْ غَيْرَ جَازِمَةٍ.</span><p class="rule-study-text">В восьми перечисленных случаях ответ условия обязательно присоединяется связующей фа независимо от того, управляет ли условная частица джазмом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Восемь обязательных случаев</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرَّقْمُ</span><span class="rule-table-ru">номер</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صُورَةُ جَوَابِ الشَّرْطِ</span><span class="rule-table-ru">форма ответа условия</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">١</span><span class="rule-table-ru">первый</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَبْدَأُ الْجَوَابُ بِمُبْتَدَأٍ أَوْ ضَمِيرٍ</span><span class="rule-table-ru">ответ начинается с мубтада или местоимения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٢</span><span class="rule-table-ru">второй</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ طَلَبِيٌّ</span><span class="rule-table-ru">глагол побуждения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَمْرٌ، أَوْ نَهْيٌ، أَوِ اسْتِفْهَامٌ</span><span class="rule-table-ru">приказ, запрет или вопрос</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٣</span><span class="rule-table-ru">третий</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ جَامِدٌ</span><span class="rule-table-ru">неизменяемый по временам глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَيْسَ، عَسَى، نِعْمَ، بِئْسَ</span><span class="rule-table-ru">ляйса, ‘аса, ни‘ма, би’са</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٤</span><span class="rule-table-ru">четвёртый</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِقَدْ</span><span class="rule-table-ru">перед ответом стоит «кад»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">قَدْ</span><span class="rule-table-ru">частица «уже; действительно»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٥</span><span class="rule-table-ru">пятый</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِمَا النَّافِيَةِ</span><span class="rule-table-ru">перед ответом стоит отрицательная «ма»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">отрицательная частица</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٦</span><span class="rule-table-ru">шестой</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِلَنْ</span><span class="rule-table-ru">перед ответом стоит «лян»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَنْ</span><span class="rule-table-ru">отрицание будущего времени</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٧</span><span class="rule-table-ru">седьмой</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِالسِّينِ أَوْ سَوْفَ</span><span class="rule-table-ru">перед ответом стоит син или сауфа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">سَـ، سَوْفَ</span><span class="rule-table-ru">показатели будущего времени</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٨</span><span class="rule-table-ru">восьмой</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِكَأَنَّمَا</span><span class="rule-table-ru">перед ответом стоит «как будто»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَأَنَّمَا</span><span class="rule-table-ru">словно; как будто</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">1. Ответ — именное предложение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ يَجْتَهِدْ فَهُوَ نَاجِحٌ.</span><span class="rule-table-ru">Кто усердствует, тот преуспевает.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فَهُوَ نَاجِحٌ</span><span class="rule-table-ru">то он преуспевает; именное предложение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-predicate" dir="rtl" lang="ar">﴿ وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ﴾</span><span class="rule-example-ru">«Когда Мои рабы спрашивают тебя обо Мне, то Я близок».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-predicate" dir="rtl" lang="ar">﴿ وَإِنْ يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ﴾</span><span class="rule-example-ru">«А если Он коснётся тебя благом, то Он способен на всякую вещь».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">2. Ответ — побуждение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الطَّلَبِ</span><span class="rule-table-ru">вид побуждения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلُ الْأَمْرِ</span><span class="rule-table-ru">форма приказа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا عَطَسْتَ فَاحْمَدِ اللَّهَ.</span><span class="rule-table-ru">Когда чихнёшь, восхвали Аллаха.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَاحْمَدِ اللَّهَ</span><span class="rule-table-ru">восхвали Аллаха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ الْمَجْزُومُ بِلَامِ الْأَمْرِ</span><span class="rule-table-ru">глагол в джазме с лямом приказа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا نِمْتَ فَلْتَذْكُرِ اللَّهَ.</span><span class="rule-table-ru">Когда ляжешь спать, вспоминай Аллаха.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَلْتَذْكُرِ اللَّهَ</span><span class="rule-table-ru">пусть ты вспоминаешь Аллаха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">النَّهْيُ</span><span class="rule-table-ru">запрет</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا سَمِعْتُمْ بِالطَّاعُونِ فِي أَرْضٍ فَلَا تَدْخُلُوهَا.</span><span class="rule-table-ru">Если услышите о чуме в какой-либо земле, не входите в неё.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَلَا تَدْخُلُوهَا</span><span class="rule-table-ru">не входите в неё</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">النَّهْيُ</span><span class="rule-table-ru">запрет</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِنْ تُرِدِ الْجَنَّةَ فَلَا تَعْصِ اللَّهَ.</span><span class="rule-table-ru">Если желаешь Рая, не ослушивайся Аллаха.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَلَا تَعْصِ اللَّهَ</span><span class="rule-table-ru">не ослушивайся Аллаха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْتِفْهَامُ</span><span class="rule-table-ru">вопрос</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِنْ أَنْجَحْ فَهَلْ أَحْصُلُ عَلَى هَدِيَّةٍ؟</span><span class="rule-table-ru">Если я преуспею, получу ли я подарок?</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَهَلْ أَحْصُلُ عَلَى هَدِيَّةٍ؟</span><span class="rule-table-ru">получу ли я подарок?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْتِفْهَامُ</span><span class="rule-table-ru">вопрос</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا سَأَلَ عَنْكَ الْمُدَرِّسُ فَمَاذَا أَقُولُ لَهُ؟</span><span class="rule-table-ru">Когда преподаватель спросит о тебе, что мне сказать ему?</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَمَاذَا أَقُولُ لَهُ؟</span><span class="rule-table-ru">что мне сказать ему?</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي ﴾</span><span class="rule-example-ru">«Если вы любите Аллаха, то следуйте за мной».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَإِنْ جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى اللَّهِ ﴾</span><span class="rule-example-ru">«Если они склонятся к миру, то и ты склонись к нему и уповай на Аллаха».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">3. Ответ — неизменяемый по временам глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ الْجَامِدُ</span><span class="rule-table-ru">неизменяемый глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَيْسَ</span><span class="rule-table-ru">не является</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَنْ غَشَّنَا فَلَيْسَ مِنَّا.</span><span class="rule-table-ru">Кто обманывает нас, тот не из нас.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نِعْمَ</span><span class="rule-table-ru">как хорош</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِنْ تَصْدُقْ فَنِعْمَ الرَّجُلُ أَنْتَ.</span><span class="rule-table-ru">Если будешь правдив, то какой хороший ты человек.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى</span><span class="rule-table-ru">возможно; есть надежда</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِنْ تَتُبْ فَعَسَى أَنْ يَتُوبَ اللَّهُ عَلَيْكَ.</span><span class="rule-table-ru">Если покаешься, то, возможно, Аллах примет твоё покаяние.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بِئْسَ</span><span class="rule-table-ru">как плох</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِنَ الْأَفْعَالِ الْجَامِدَةِ الْمَذْكُورَةِ</span><span class="rule-table-ru">назван автором среди неизменяемых глаголов</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">4–8. Ответ начинается с указанного элемента</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ غَيْرُ الْقُرْآنِيِّ</span><span class="rule-table-ru">обычный пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِقَدْ</span><span class="rule-table-ru">перед ответом стоит «кад»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ يَتَّقِ اللَّهَ فَقَدْ فَازَ.</span><span class="rule-table-ru">Кто боится Аллаха, тот уже преуспел.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَقَدْ فَازَ</span><span class="rule-table-ru">тот уже преуспел</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِمَا النَّافِيَةِ</span><span class="rule-table-ru">перед ответом стоит отрицательная «ма»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْمَا تَكُنِ الظُّرُوفُ فَمَا أَكْذِبُ.</span><span class="rule-table-ru">Какими бы ни были обстоятельства, я не солгу.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَمَا أَكْذِبُ</span><span class="rule-table-ru">я не солгу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِلَنْ</span><span class="rule-table-ru">перед ответом стоит «лян»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَنْ يَلْبَسَهُ فِي الْآخِرَةِ.</span><span class="rule-table-ru">Кто носил шёлк в этом мире, тот не наденет его в Последней жизни.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَلَنْ يَلْبَسَهُ</span><span class="rule-table-ru">тот не наденет его</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِلَنْ</span><span class="rule-table-ru">перед ответом стоит «лян»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْمَا تَقُلْ لِي فَلَنْ أُصَدِّقَكَ.</span><span class="rule-table-ru">Что бы ты мне ни сказал, я не поверю тебе.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَلَنْ أُصَدِّقَكَ</span><span class="rule-table-ru">я не поверю тебе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِالسِّينِ</span><span class="rule-table-ru">перед ответом стоит син будущего времени</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا سَافَرْتَ فَسَأُسَافِرُ مَعَكَ.</span><span class="rule-table-ru">Если ты отправишься в поездку, я поеду с тобой.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَسَأُسَافِرُ مَعَكَ</span><span class="rule-table-ru">я поеду с тобой</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَسْبُوقٌ بِكَأَنَّمَا</span><span class="rule-table-ru">перед ответом стоит «как будто»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا عَصَيْتَ الْأَمِيرَ فَكَأَنَّمَا عَصَيْتَ الرَّسُولَ.</span><span class="rule-table-ru">Если ослушаешься правителя, то словно ослушаешься Посланника.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَكَأَنَّمَا عَصَيْتَ الرَّسُولَ</span><span class="rule-table-ru">словно ослушаешься Посланника</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ إِنْ يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَهُ مِنْ قَبْلُ ﴾</span><span class="rule-example-ru">«Если он украл, то прежде украл и его брат».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ ﴾</span><span class="rule-example-ru">«А если ты не сделаешь этого, то не донесёшь Его послание».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَإِنْ تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُ أُخْرَى ﴾</span><span class="rule-example-ru">«А если вы станете затруднять друг друга, то его будет кормить другая женщина».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَمَنْ أَحْيَاهَا فَكَأَنَّمَا أَحْيَا النَّاسَ جَمِيعًا ﴾</span><span class="rule-example-ru">«А кто оживил её, тот словно оживил всех людей».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Форма ответа после связующей фа</span><span class="rule-main-ar ar-tone-jazm" dir="rtl" lang="ar">لَا يُجْزَمُ جَوَابُ الشَّرْطِ إِذَا اقْتَرَنَ بِالْفَاءِ، وَإِنَّمَا يَكُونُ فِي مَحَلِّ جَزْمٍ إِذَا كَانَتْ أَدَاةُ الشَّرْطِ جَازِمَةً.</span><p class="rule-study-text">После связующей фа сам ответ не получает внешнего признака джазма. При управляющей условной частице вся конструкция ответа находится в синтаксическом месте джазма.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: إِذَا اجْتَهَدْتَ فَأَنْتَ نَاجِحٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا</span><span class="rule-table-ru">когда; если</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ زَمَانٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ.</span><span class="rule-table-ru">обстоятельственное имя времени, построенное на сукуне, в синтаксическом месте винительного падежа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">غَيْرُ جَازِمٍ</span><span class="rule-table-ru">не управляет джазмом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِجْتَهَدْتَ</span><span class="rule-table-ru">ты усердствовал</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">جُمْلَةُ الشَّرْطِ مِنَ الْفِعْلِ وَالْفَاعِلِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.</span><span class="rule-table-ru">условное предложение из глагола и исполнителя находится в синтаксическом месте родительного падежа как второй член идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ الشَّرْطِ</span><span class="rule-table-ru">условное предложение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْفَاءُ</span><span class="rule-table-ru">связующая фа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَوَابٍ وَرَبْطٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица ответа и связи, построенная на фатхе и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ</span><span class="rule-table-ru">не является членом предложения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْتَ</span><span class="rule-table-ru">ты</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرٌ مُنْفَصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.</span><span class="rule-table-ru">отдельное местоимение, построенное на фатхе, в синтаксическом месте именительного падежа как мубтада</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">نَاجِحٌ</span><span class="rule-table-ru">преуспевающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">хабар в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-table-ru">хабар</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ أَنْتَ نَاجِحٌ</span><span class="rule-table-ru">предложение «ты преуспеваешь»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ جَوَابِ الشَّرْطِ لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ؛ لِأَنَّ إِذَا غَيْرُ جَازِمَةٍ.</span><span class="rule-table-ru">предложение ответа условия не имеет синтаксического места, поскольку إِذَا не управляет джазмом</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا مَحَلَّ لَهَا</span><span class="rule-table-ru">не имеет синтаксического места</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: إِنْ تَجْتَهِدْ فَأَنْتَ نَاجِحٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنْ</span><span class="rule-table-ru">если</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ شَرْطٍ جَازِمٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">управляющая условная частица, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَدَاةٌ جَازِمَةٌ</span><span class="rule-table-ru">управляет джазмом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَجْتَهِدْ</span><span class="rule-table-ru">ты усердствуешь</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ فِعْلٌ مُضَارِعٌ مَجْزُومٌ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ.</span><span class="rule-table-ru">глагол условия — глагол настоящего-будущего времени в джазме; признак джазма — сукун</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ</span><span class="rule-table-ru">глагол условия</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَأَنْتَ نَاجِحٌ</span><span class="rule-table-ru">то ты преуспеваешь</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ مِنَ الْمُبْتَدَأِ وَالْخَبَرِ فِي مَحَلِّ جَزْمٍ؛ لِأَنَّ إِنْ جَازِمَةٌ.</span><span class="rule-table-ru">ответ условия из мубтада и хабара находится в синтаксическом месте джазма, поскольку إِنْ управляет джазмом</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِي مَحَلِّ جَزْمٍ</span><span class="rule-table-ru">в синтаксическом месте джазма</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: مَنْ يَزُرْنِي فَسَأَزُورُهُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ</span><span class="rule-table-ru">кто</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ٱسْمُ شَرْطٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ، وَجُمْلَتَا الشَّرْطِ وَالْجَوَابِ فِي مَحَلِّ رَفْعٍ خَبَرٌ.</span><span class="rule-table-ru">условное имя, построенное на сукуне, в синтаксическом месте именительного падежа как мубтада; предложения условия и ответа находятся в синтаксическом месте именительного падежа как хабар</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَزُرْ</span><span class="rule-table-ru">посетит</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ فِعْلٌ مُضَارِعٌ مَجْزُومٌ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</span><span class="rule-table-ru">глагол условия в джазме; признак — сукун; исполнитель — скрытое местоимение «он»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: هُوَ</span><span class="rule-table-ru">исполнитель — «он»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النُّونُ</span><span class="rule-table-ru">нун в يَزُرْنِي</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ وِقَايَةٍ مَبْنِيٌّ عَلَى الْكَسْرِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">защитная буква нун, построенная на касре и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ وِقَايَةٍ</span><span class="rule-table-ru">защитная нун</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа в يَزُرْنِي</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.</span><span class="rule-table-ru">присоединённое местоимение, построенное на сукуне, в синтаксическом месте винительного падежа как прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْفَاءُ</span><span class="rule-table-ru">связующая фа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَوَابٍ وَرَبْطٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица ответа и связи, построенная на фатхе и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَوَابٍ وَرَبْطٍ</span><span class="rule-table-ru">частица ответа и связи</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">السِّينُ</span><span class="rule-table-ru">син будущего времени</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ ٱسْتِقْبَالٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица будущего времени, построенная на фатхе и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ ٱسْتِقْبَالٍ</span><span class="rule-table-ru">частица будущего времени</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَزُورُ</span><span class="rule-table-ru">я посещу</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنَا.</span><span class="rule-table-ru">глагол настоящего-будущего времени в именительном состоянии; признак — дамма; исполнитель — скрытое местоимение «я»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: أَنَا</span><span class="rule-table-ru">исполнитель — «я»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْهَاءُ</span><span class="rule-table-ru">местоимение «его»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.</span><span class="rule-table-ru">присоединённое местоимение, построенное на дамме, в синтаксическом месте винительного падежа как прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ فَسَأَزُورُهُ</span><span class="rule-table-ru">предложение «то я посещу его»</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">جُمْلَةُ جَوَابِ الشَّرْطِ فِي مَحَلِّ جَزْمٍ.</span><span class="rule-table-ru">предложение ответа условия находится в синтаксическом месте джазма</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِي مَحَلِّ جَزْمٍ</span><span class="rule-table-ru">в синтаксическом месте джазма</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'Шарх перечисляет восемь случаев обязательной связующей фа в ответе условия и поясняет различие синтаксического места ответа после управляющего и неуправляющего условия.', 'يَجِبُ اقْتِرَانُ جَوَابِ الشَّرْطِ بِالْفَاءِ، سَوَاءٌ أَكَانَتْ أَدَاةُ الشَّرْطِ جَازِمَةً أَمْ غَيْرَ جَازِمَةٍ، إِذَا كَانَ الْجَوَابُ جُمْلَةً اسْمِيَّةً، أَوْ فِعْلًا طَلَبِيًّا، أَوْ فِعْلًا جَامِدًا، أَوْ كَانَ مَسْبُوقًا بِقَدْ أَوْ مَا النَّافِيَةِ أَوْ لَنْ أَوِ السِّينِ أَوْ سَوْفَ أَوْ كَأَنَّمَا. وَإِذَا اقْتَرَنَ جَوَابُ الشَّرْطِ الْجَازِمِ بِالْفَاءِ لَمْ يُجْزَمْ لَفْظُهُ، وَإِنَّمَا يَكُونُ فِي مَحَلِّ جَزْمٍ.'),
    ('Мединский курс (Том 3)', '14', 'النِّسْبَةُ إِلَى مَا آخِرُهُ تَاءُ التَّأْنِيثِ (нисба от слов с конечной та женского рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">إِذَا نُسِبَ إِلَى ٱسْمٍ مَخْتُومٍ بِتَاءِ التَّأْنِيثِ حُذِفَتْ تَاءُ التَّأْنِيثِ.</span><p class="rule-study-text">Если исходное имя оканчивается на та женского рода, при образовании нисбы эта буква удаляется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْأَصْلِيُّ</span><span class="rule-table-ru">исходное имя и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ٱسْمُ النِّسْبَةِ</span><span class="rule-table-ru">форма нисбы и русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَّةُ</span><span class="rule-table-ru">Мекка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكِّيٌّ</span><span class="rule-table-ru">мекканский; житель Мекки</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَدْرَسَةٌ</span><span class="rule-table-ru">школа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَدْرَسِيٌّ</span><span class="rule-table-ru">школьный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَرْدَةٌ</span><span class="rule-table-ru">роза</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَرْدِيٌّ</span><span class="rule-table-ru">розовый; относящийся к розе</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'При образовании имени отношения от слова с конечной та женского рода эта та удаляется перед суффиксом нисбы.', 'إِذَا نُسِبَ إِلَى ٱسْمٍ مَخْتُومٍ بِتَاءِ التَّأْنِيثِ حُذِفَتْ تَاءُ التَّأْنِيثِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'إِذَا الشَّرْطِيَّةُ
إِذَا : ظَرْفٌ لِمَا يُسْتَقْبَلُ مِنَ الزَّمَانِ مبني على السكون .
متضمن معنى الشرط لكنه غير جازم .
* تدخل غالباً على الفعل الماضي فَتُحَوَّلُ مَعْنَاه إلى الْمُسْتَقْبَل .
وقد تدخلُ على المضارع في الشَّرط ، وفي الجواب .
الأمثلة :
نحو قوله ( : " إِذَا جَاءَ رَمَضَانُ فُتِحَتْ أَبْوَابُ الْجَنَّةِ " .
ونحو : إذا رَنَّ الْجَرَسُ خَرَجَ الطُّلابُ من الفصلِ . إذا حَضَرَ الماءُ بَطَلَ التَّيَمُّمُ .
قال الشاعر : والنَّفْسُ رَاغِبَةٌ إذا رَغَّبْتَها           وَإِذَا تُرَدُّ إلى قَلِيلٍ تَقْنَـعُ
فعل الشرط ماضٍ        فعل الشرط        جواب الشرط
والجواب محذوف      مضارع مرفوع      مضارع مرفوع', 55, 56, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '14' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'وُجُوبُ اقْتِرَانِ جَوَابِ الشَّرْطِ بِالْفَاءِ
يجبُ اقترانُ جواب الشَّرط بالفاء ( سَوَاءٌ أكانت أداة الشرط جازمة ، أم غير جازمة )
في المواضع الآتِيَة :
1- إذا كان الجوابُ جملةً اسميَّةً ، نحو قوله تعالى : ﴿ وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ﴾
ونحو قوله تعالى: ﴿ وَإِنْ يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ﴾
ونحو قولك : مَنْ يجتهدْ فهو ناجحٌ .
2- إذا كان الجوابُ فعلاً طَلَبِيّاً . ومِنْ أنواع الطَّلب : الأمر ، والنَّهي ، والاستفهام .
مثال الأمر : قال تعالى : ﴿ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي ﴾ ونحو قولك :
إذا عَطَسْتَ فَاحْمَدِ اللهَ ، ونحو : إذا نِمْتَ فَلْتَذْكُرِ اللهَ .
* الطَّلَبُ بالأَمْرِ : يشمل فعل الأمر ، والمضارع المجزوم بلام الأمر .
مثال النَّهي : قال ( : " إذا سَمِعْتُمْ بالطَّاعُونِ فِي أَرْضٍ فَلاَ تَدْخُلُوهَا .. " ونحو قولك : إِنْ تُرِدِ الجنَّةَ فلا تَعْصِ اللهَ .
مثال الاستفهام : نحو قولك : إِنَ أنجحْ فَهَلْ أَحْصُلُ على هَدِيَّة ، ونحو قولك :
إذا سألَ عنك المدرَّس فماذا أقولُ له ؟
3- إذا كان الجوابُ فِعْلاً جَامِداً . الأفعال الجامدة ( ليسَ ، وعَسَى، ونِعْمَ ، وبِئْسَ ) .
نحو قوله ( : " مَنْ غَشَّنَا فَلَيْسَ مِنَّا " ونحو : إِنْ تَصْدُقْ فَنِعْمَ الرجلُ أنت .
ونحو : إِنْ تَتُبْ فَعَسَى أَنْ يتوبَ اللهُ عليك .
4- إذا كان الجوابُ مَسْبُوقاً بـ ( قَدْ ) نحو قوله تعالى: ﴿ إِنْ يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَهُ مِنْ قَبْلُ ﴾
ونحو قولك : مَنْ يَتَّقِ اللهَ فَقَدْ فَازَ .
5- إذا كان الجوابُ مسبوقاً بـ ( مَا ) النَّافِيَةِ ، نحو قوله تعالى : ﴿ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ ﴾
ونحو قولك : مَهْمَا تَكُنِ الظُّروفُ فَمَا أَكْذِبُ .
6- إذا كان الجوابُ مسبوقاً بـ ( لَنْ ) ، نحو قوله ( : " مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا
فلَنْ يَلْبَسَهُ فِي الآخِرَةِ " ، ونحو قولك : مهما تَقُلْ لي فَلَنْ أُصُدَّقَك .
7- إذا كان الجوابُ مسبوقاً بالسَّين ، أو سَوْفَ ، نحو قوله تعالى : ﴿ وَإِنْ تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُ أُخْرَى ﴾
وقوله تعالى : ﴿ وَإِنْ جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى اللَّهِ ﴾
ونحو قولك : إذا سافرْتَ فسَأُسَافِرُ معك .
8- إذا كان الجواب مسبوقاً بـ ( كَأَنَّمَا ) نحو قوله تعالى: ﴿ وَمَنْ أَحْيَاهَا فَكَأَنَّمَا أَحْيَا النَّاسَ جَمِيعًا ﴾
ونحو قولك: إذا عَصَيْتَ الأَمِيرَ فكأنَّما عَصَيْتَ الرسولَ .
* لا يُجْزَمُ جوابُ الشَّرْطِ إذا اقترنَ بالفاء ، وإنَّما يكونُ في محلِّ جزمٍ .
الإعراب : إذا اجتهدْتَ فأنت ناجحٌ .
إذا   : ظرف زمان مبني على السكون في محل نصب .
اجتهدْت : جملة الشرط ( من الفعل والفاعل ) في محل جر مضاف إليه .
فأنت ناجحٌ : الفاء : حرف جواب وربط مبني على الفتح لا محلّ له من الإعراب .
أنت : ضمير منفصل مبني على الفتح في محل رفع مبتدأ .
ناجح : خبر مرفوع وعلامة رفعه الضمة الظاهرة .
وجملة جواب الشرط ( أنت ناجح ) لا محل لها من الإعراب. (لأنَّ الشَّرطَ إذا غير جازم).
* إِنْ تجتهدْ فأنت ناجحٌ .
إِنْ : حرف شرط جازم مبني على السكون لا محلّ له من الإعراب .
تجتهدْ : فعلُ الشرطِ فعلٌ مضارع مجزوم وعلامة جزمه السّكون .
فأنت ناجحٌ : جواب الشّرط (من المبتدأ والخبر) في محل جزم . (لأنَّ الشَّرط إِنْ جازم ).
* مَنْ يَزُرْنِي فَسَأَزُورُهُ .
منْ : اسم شرط مبني على السكون في محل رفع مبتدأ ، وجملتا الشرط والجواب
في محل رفع خبر .
يزرْني : يَزُرْ . فعلُ الشرطِ فعلٌ مضارع مجزوم وعلامة جزمه السكون، والفاعل
ضمير مستتر تقديره ( هو ) .
والنون : حرف وِقَايَة مبني على الكسر لا محلّ له من الإعراب .
والياء  : ضمير مُتَّصل مبني على السكون في محل نصب مفعول به .
فَسَأزورُهُ : الفاء  : حرف جواب وربط مبني على الفتح لا محلّ له من الإعراب .
السين : حرف اسْتِقْبَال مبني على الفتح لا محلّ له من الإعراب .
أزورُ : فعل مضارع مرفوع وعلامة رفعه الضمة، والفاعل ضمير مستتر تقديره
( أنا ) .
والهاء : ضمير مُتَّصل مبني على الضم في محل نصب مفعول به .
وجملة جواب الشرط ( سأزوره ) في محل جزم .', 56, 59, 1
